/** Projeto independente. Não reutiliza IDs nem dados do Salém. */
const PDA = Object.freeze({parent:'1wKO6B73R2e-H8E5R_vxRAHmUOIFz3bu7',name:'Povo das Águas',tz:'America/Sao_Paulo',maxBytes:5*1024*1024});
const SCHEMA = Object.freeze({
 Pessoas:['nome','cpf','nascimento','telefone','tipoVia','via','numero','complemento','bairro','cidade','uf','entidade','outraEntidade','analfabeto'],
 Atendimentos:['pessoaId','demanda','referencia','parcelas','outrosCasos','observacoes','responsavel','situacao','folderId','revisao','conferencia','enderecamento','secaoJudiciaria','valorCausa','localData'],
 Documentos:['atendimentoId','categoria','fileId','url','nome','hash','mime','substituiId','vigente','vencimento','terceiro','conferido','declaracaoTerceiro','processoCompleto','anexoPresente','rogo','testemunhas','observacoes'],
 Pendencias:['atendimentoId','descricao','responsavel','situacao'],
 Minutas:['atendimentoId','fileId','url','numero','situacao','snapshot','templateId','templateModified','revisor','revisadaEm'],
 Historico:['entidade','registroId','antes','depois','operacao'],
 Configuracoes:['chave','valor'],Usuarios:['email','perfil','ativo'],
 Distribuicao:['atendimentoId','processoId','numero','juizo','data','responsavel','protocoloId'],
 Processos:['pessoaId','atendimentoId','numero','juizo','distribuidoEm','responsavel','movimentacoes'],
 Operacoes:['hash','resultado']
});
const COMMON=['id','versao','criadoEm','alteradoEm','usuario'];
const DEFAULTS={rascunhos:'PENDENTE',vencimentoFuturo:'PENDENTE',anexoOrientacao:'',templateId:'',templateAprovado:false,
 entidades:['COPAPEL — COLÔNIA DOS PESCADORES E AQUICULTORES PROFISSIONAIS ARTESANAIS DE PELOTAS','COLÔNIA Z-1','COLÔNIA Z-2','COLÔNIA Z-3','COLÔNIA Z-11','Outro'],
 municipios:['Rio Grande','Pelotas','São José do Norte'],demandas:['Seguro-Defeso 2025'],
 categorias:['RG_CPF','RESIDENCIA','PROCESSO_ADMINISTRATIVO','PESCA','PROCURACAO','HIPOSSUFICIENCIA'],
 situacoes:['EM_PREPARACAO','ENCAMINHADO','CONFERIDO']};
const ROLES={CONSULTA:['consulta'],CADASTRO:['consulta','cadastro'],CONFERENCIA:['consulta','cadastro','retificacao','conferencia'],JURIDICO:['consulta','cadastro','retificacao','conferencia','minuta'],ADMIN:['consulta','cadastro','retificacao','conferencia','minuta','administracao']};
function props_(){return PropertiesService.getScriptProperties();
}
function fail_(message){throw new Error(message);
}
function required_(v,label){if(v===undefined||v===null||String(v).trim()==='')fail_('Informe '+label+'.');
return v;
}
function uid_(){return Utilities.getUuid();
}
function hash_(value){return Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256,typeof value==='string'?value:JSON.stringify(value)).map(x=>('0'+((x+256)%256).toString(16)).slice(-2)).join('');
}
function id_(prefix,key){return prefix+'_'+hash_(key).slice(0,28);
}
function now_(){return new Date().toISOString();
}
function bool_(v){return v===true||v==='true';
}
function clone_(v){return JSON.parse(JSON.stringify(v));
}
function cfg_(){const c=clone_(DEFAULTS);
all_('Configuracoes').forEach(r=>{c[r.chave]=JSON.parse(r.valor);
});
return c;
}

let DATA_CACHE = {};
function resetData_(){DATA_CACHE={};
}
function ss_(){const id=props_().getProperty('SPREADSHEET_ID');
if(!id)fail_('Execute instalar pelo editor do Apps Script.');
return SpreadsheetApp.openById(id);
}
function headers_(entity){if(!SCHEMA[entity])fail_('Entidade inválida.');
return COMMON.concat(SCHEMA[entity]);
}
function all_(entity){if(DATA_CACHE[entity])return DATA_CACHE[entity];
const sh=ss_().getSheetByName(entity);
const rows=sh.getDataRange().getDisplayValues();
const heads=headers_(entity);
if(JSON.stringify(rows[0])!==JSON.stringify(heads))fail_('Cabeçalhos alterados: '+entity);
return DATA_CACHE[entity]=rows.slice(1).filter(r=>r[0]).map(r=>Object.fromEntries(heads.map((h,i)=>[h,h==='versao'?Number(r[i]):r[i]])));
}
function get_(entity,id){return all_(entity).find(r=>r.id===id)||fail_('Registro não encontrado: '+entity);
}
function row_(entity,id){const sh=ss_().getSheetByName(entity);
const values=sh.getRange(1,1,Math.max(sh.getLastRow(),1),1).getDisplayValues();
const i=values.findIndex(r=>r[0]===id);
return i<0?null:i;
}
function record_(entity,id,data,before,user){const r={id,versao:before?before.versao+1:1,criadoEm:before?before.criadoEm:now_(),alteradoEm:now_(),usuario:user};
SCHEMA[entity].forEach(k=>r[k]=data[k]===undefined?'':data[k]);
return r;
}
function change_(ctx,entity,id,data,version){const before=all_(entity).find(r=>r.id===id);
if(before&&Number(version)!==before.versao)fail_('CONFLITO: o registro mudou. Reabra a ficha antes de salvar.');
const after=record_(entity,id,data,before,ctx.email);
ctx.changes.push({entity,before:before||null,after});
return after;
}
/** Atualização de dados, auditoria e recibo idempotente em uma única transação Sheets. */
function commit_(ctx,result){const changes=ctx.changes.slice();
ctx.changes.forEach(c=>changes.push({entity:'Historico',after:record_('Historico',uid_(),{entidade:c.entity,registroId:c.after.id,antes:JSON.stringify(c.before),depois:JSON.stringify(c.after),operacao:ctx.op},null,ctx.email)}));
changes.push({entity:'Operacoes',after:record_('Operacoes',ctx.op,{hash:ctx.hash,resultado:JSON.stringify(result)},null,ctx.email)});
 const next={};
const requests=[];
changes.forEach(c=>{const sh=ss_().getSheetByName(c.entity);
let index=row_(c.entity,c.after.id);
if(index===null){if(next[c.entity]===undefined)next[c.entity]=sh.getLastRow();
index=next[c.entity]++;
}if(index>=sh.getMaxRows())requests.push({appendDimension:{sheetId:sh.getSheetId(),dimension:'ROWS',length:index-sh.getMaxRows()+1}});
const values=headers_(c.entity).map(k=>({userEnteredValue:{stringValue:String(c.after[k]===undefined?'':c.after[k])}}));
requests.push({updateCells:{range:{sheetId:sh.getSheetId(),startRowIndex:index,endRowIndex:index+1,startColumnIndex:0,endColumnIndex:values.length},rows:[{values}],fields:'userEnteredValue'}});
});
 Sheets.Spreadsheets.batchUpdate({requests},ss_().getId());
SpreadsheetApp.flush();
resetData_();
return result;
}
function version_(row,expected){if(row.versao!==Number(expected))fail_('CONFLITO: registro alterado por outro usuário. Reabra a ficha.');
}
function touch_(ctx,a){return change_(ctx,'Atendimentos',a.id,Object.assign({},a,{revisao:Number(a.revisao||0)+1,conferencia:'',situacao:'EM_PREPARACAO'}),a.versao);
}
function snapshot_(a,p){return hash_({atendimento:a,pessoa:p,documentos:all_('Documentos').filter(d=>d.atendimentoId===a.id&&bool_(d.vigente)),pendencias:all_('Pendencias').filter(d=>d.atendimentoId===a.id)});
}

function identity_(){const email=Session.getActiveUser().getEmail().toLowerCase().trim();
if(!email)fail_('Identidade Google indisponível. Acesso bloqueado; revise a implantação.');
return email;
}
function authorize_(permission){const email=identity_();
const u=all_('Usuarios').find(r=>r.email===email&&bool_(r.ativo));
if(!u||!(ROLES[u.perfil]||[]).includes(permission))fail_('Acesso não autorizado para '+permission+'.');
return email;
}
function lock_(fn){const lock=LockService.getScriptLock();
if(!lock.tryLock(30000))fail_('Sistema ocupado. Tente novamente com a mesma operação.');
try{return fn();
}finally{lock.releaseLock();
}}

/** Executar somente no editor, nunca pelo navegador. Configure OWNER_EMAIL nas propriedades primeiro. */
function instalar(){return lock_(function(){resetData_();
const email=identity_();
if(email!==props_().getProperty('OWNER_EMAIL'))fail_('Configure OWNER_EMAIL com o e-mail da conta responsável, nas propriedades do script.');
const parent=DriveApp.getFolderById(PDA.parent);
let rootId=props_().getProperty('ROOT_FOLDER_ID');
if(!rootId){const name=PDA.name+' — '+ScriptApp.getScriptId();
const iter=parent.getFoldersByName(name);
const folder=iter.hasNext()?iter.next():parent.createFolder(name);
if(iter.hasNext())fail_('Pastas de instalação duplicadas; selecione ROOT_FOLDER_ID manualmente.');
rootId=folder.getId();
props_().setProperty('ROOT_FOLDER_ID',rootId);
}const root=DriveApp.getFolderById(rootId);
let sid=props_().getProperty('SPREADSHEET_ID');
if(!sid){const name='PDA Banco — '+ScriptApp.getScriptId();
const matches=DriveApp.getFilesByName(name);
const found=[];
while(matches.hasNext()){const f=matches.next();
if(f.getMimeType()===MimeType.GOOGLE_SHEETS&&!f.isTrashed())found.push(f);
}if(found.length>1)fail_('Mais de um banco encontrado; defina SPREADSHEET_ID.');
sid=found.length?found[0].getId():SpreadsheetApp.create(name).getId();
props_().setProperty('SPREADSHEET_ID',sid);
}DriveApp.getFileById(sid).moveTo(root);
const ss=SpreadsheetApp.openById(sid);
ss.setSpreadsheetTimeZone(PDA.tz);
Object.keys(SCHEMA).forEach(entity=>{const heads=headers_(entity);
const sh=ss.getSheetByName(entity)||ss.insertSheet(entity);
if(sh.getLastRow()===0){sh.getRange(1,1,1,heads.length).setValues([heads]);
sh.setFrozenRows(1);
sh.getRange(1,1,1,heads.length).setBackground('#12364a').setFontColor('#ffffff');
}else if(JSON.stringify(sh.getRange(1,1,1,sh.getLastColumn()).getDisplayValues()[0])!==JSON.stringify(heads))fail_('Estrutura divergente: '+entity+'. Nenhum cabeçalho será sobrescrito.');
sh.getRange(1,1,sh.getMaxRows(),heads.length).setNumberFormat('@');
});
SpreadsheetApp.flush();
const ctx={email,op:'install_'+uid_(),hash:'installation',changes:[]};
Object.keys(DEFAULTS).forEach(chave=>{if(!all_('Configuracoes').some(r=>r.chave===chave))change_(ctx,'Configuracoes',id_('CFG',chave),{chave,valor:JSON.stringify(DEFAULTS[chave])});
});
if(!all_('Usuarios').some(r=>r.email===email))change_(ctx,'Usuarios',id_('USR',email),{email,perfil:'ADMIN',ativo:true});
return commit_(ctx,{planilha:ss.getUrl(),pasta:root.getUrl(),mensagem:'Instalação estrutural concluída; homologação Google ainda necessária.'});
});
}

function cpf_(input){const s=String(input||'').replace(/\D/g,'');
if(!/^\d{11}$/.test(s)||/^(\d)\1+$/.test(s))fail_('CPF inválido.');
for(let j=9;
j<11;
j++){let n=0;
for(let i=0;
i<j;
i++)n+=Number(s[i])*(j+1-i);
let d=(n*10)%11;
if(d===10)d=0;
if(d!==Number(s[j]))fail_('CPF inválido.');
}return s;
}
function date_(s){if(!/^\d{2}\/\d{2}\/\d{4}$/.test(s||''))fail_('Data deve usar DD/MM/AAAA.');
const [d,m,y]=s.split('/').map(Number);
const date=new Date(Date.UTC(y,m-1,d));
if(date.getUTCFullYear()!==y||date.getUTCMonth()!==m-1||date.getUTCDate()!==d)fail_('Data inválida.');
return date;
}
function today_(){return date_(Utilities.formatDate(new Date(),PDA.tz,'dd/MM/yyyy'));
}
function validatePerson_(input,c,complete){const p={};
SCHEMA.Pessoas.forEach(k=>p[k]=typeof input[k]==='string'?input[k].trim():input[k]);
p.cpf=cpf_(p.cpf);
required_(p.nome,'nome completo');
if(p.nome.length>200)fail_('Nome muito longo.');
if(complete)['nascimento','telefone','tipoVia','via','numero','bairro','cidade','uf','entidade','analfabeto'].forEach(k=>required_(p[k],k));
if(p.nascimento&&date_(p.nascimento)>today_())fail_('Nascimento não pode estar no futuro.');
if(p.telefone&&!/^\d{10,11}$/.test(p.telefone.replace(/\D/g,'')))fail_('Telefone deve conter DDD e 10 ou 11 dígitos.');
if(p.uf&&!/^(AC|AL|AP|AM|BA|CE|DF|ES|GO|MA|MT|MS|MG|PA|PB|PR|PE|PI|RJ|RN|RS|RO|RR|SC|SP|SE|TO)$/.test(p.uf))fail_('UF inválida.');
if(p.cidade&&!c.municipios.includes(p.cidade))fail_('Município não cadastrado.');
if(p.entidade&&!c.entidades.includes(p.entidade))fail_('Entidade não cadastrada.');
if(p.entidade==='Outro')required_(p.outraEntidade,'outra entidade');
if(p.analfabeto&&!['SIM','NAO'].includes(p.analfabeto))fail_('Informe a condição registrada no documento de identidade.');
return p;
}
function validateAtend_(input,c){const a={};
['pessoaId','demanda','referencia','parcelas','outrosCasos','observacoes','responsavel','enderecamento','secaoJudiciaria','valorCausa','localData'].forEach(k=>a[k]=String(input[k]||'').trim());
['pessoaId','demanda','referencia','parcelas'].forEach(k=>required_(a[k],k));
if(!c.demandas.includes(a.demanda))fail_('Demanda não cadastrada.');
if(!['Todas de 2025','Somente a última de 2025','Outros casos'].includes(a.parcelas))fail_('Opção de parcelas inválida.');
if(a.parcelas==='Outros casos')required_(a.outrosCasos,'descrição dos outros casos');
if(a.responsavel&&!all_('Usuarios').some(u=>u.email===a.responsavel&&bool_(u.ativo)))fail_('Responsável não autorizado.');
return a;
}
function address_(p){return [p.tipoVia+' '+p.via,p.numero,p.complemento,p.bairro].filter(Boolean).join(', ');
}
function eligibility_(a,manual){const errors=[];
const p=get_('Pessoas',a.pessoaId),c=cfg_();
try{validatePerson_(p,c,true);
validateAtend_(a,c);
}catch(e){errors.push(e.message);
}if(c.vencimentoFuturo==='PENDENTE')errors.push('Definir política de vencimento futuro.');
if(!c.anexoOrientacao)errors.push('Identificar o anexo exigido.');
const docs=all_('Documentos').filter(d=>d.atendimentoId===a.id&&bool_(d.vigente));
c.categorias.forEach(cat=>{const ds=docs.filter(d=>d.categoria===cat);
if(!ds.length)errors.push('Anexar '+cat);
ds.forEach(d=>{if(manual&&!bool_(d.conferido))errors.push('Conferir '+d.nome);
if(cat==='RESIDENCIA'){try{const days=(today_()-date_(d.vencimento))/86400000;
if(days>60)errors.push('Comprovante vencido há mais de 60 dias.');
if(days<0&&c.vencimentoFuturo!=='ACEITAR')errors.push('Vencimento futuro não autorizado.');
}catch(e){errors.push('Residência: '+e.message);
}if(manual&&bool_(d.terceiro)&&!bool_(d.declaracaoTerceiro))errors.push('Conferir declaração de residência na própria fatura.');
}if(manual&&cat==='PROCESSO_ADMINISTRATIVO'&&(!bool_(d.processoCompleto)||!bool_(d.anexoPresente)))errors.push('Conferir processo completo e anexo.');
if(manual&&cat==='PROCURACAO'&&p.analfabeto==='SIM'&&(!bool_(d.rogo)||!bool_(d.testemunhas)))errors.push('Conferir assinatura a rogo e duas testemunhas.');
});
});
if(all_('Pendencias').some(x=>x.atendimentoId===a.id&&x.situacao!=='RESOLVIDA'))errors.push('Existem pendências abertas.');
return [...new Set(errors)];
}

function folder_(a){if(a.folderId)return DriveApp.getFolderById(a.folderId);
const p=get_('Pessoas',a.pessoaId);
const root=DriveApp.getFolderById(props_().getProperty('ROOT_FOLDER_ID'));
const name=(a.id+' — '+p.nome+' — '+a.demanda+' — '+a.referencia).slice(0,230);
const all=root.getFolders();
const matches=[];
while(all.hasNext()){const f=all.next();
if(f.getName().startsWith(a.id+' — '))matches.push(f);
}if(matches.length>1)fail_('Há pastas duplicadas para este atendimento; administração deve reconciliar.');
return matches.length?matches[0]:root.createFolder(name);
}
function upload_(ctx,q){const a=get_('Atendimentos',q.atendimentoId);
version_(a,q.versao);
const c=cfg_();
if(!c.categorias.includes(q.categoria))fail_('Categoria inválida.');
if(!['application/pdf','image/jpeg','image/png'].includes(q.mime))fail_('Use PDF, JPEG ou PNG.');
if(typeof q.base64!=='string'||q.base64.length>PDA.maxBytes*1.4)fail_('Limite de 5 MB por arquivo.');
const bytes=Utilities.base64Decode(q.base64);
if(!bytes.length||bytes.length>PDA.maxBytes)fail_('Arquivo vazio ou maior que 5 MB.');
const sig=bytes.slice(0,8).map(x=>(x+256)%256);
if((q.mime==='application/pdf'&&String.fromCharCode(...sig.slice(0,5))!=='%PDF-')||(q.mime==='image/jpeg'&&(sig[0]!==255||sig[1]!==216))||(q.mime==='image/png'&&sig.join(',')!=='137,80,78,71,13,10,26,10'))fail_('Conteúdo não corresponde ao tipo do arquivo.');
const digest=Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256,bytes).map(x=>('0'+((x+256)%256).toString(16)).slice(-2)).join('');
const prior=all_('Documentos').find(d=>d.atendimentoId===a.id&&d.categoria===q.categoria&&d.hash===digest&&bool_(d.vigente));
if(prior)return {documento:prior,atendimento:a,mensagem:'Arquivo já anexado; preservado sem duplicação.'};
if(q.categoria==='RESIDENCIA')date_(q.vencimento);
let previous=null;
if(q.substituiId){previous=get_('Documentos',q.substituiId);
if(previous.atendimentoId!==a.id||previous.categoria!==q.categoria||!bool_(previous.vigente))fail_('Substituição inválida.');
}const folder=folder_(a);
const did=id_('DOC',ctx.op);
const ext={'application/pdf':'pdf','image/jpeg':'jpg','image/png':'png'}[q.mime];
const name=a.id+'_'+q.categoria+'_'+did+'.'+ext;
const it=folder.getFilesByName(name);
const f=it.hasNext()?it.next():folder.createFile(Utilities.newBlob(bytes,q.mime,name));
if(it.hasNext())fail_('Arquivos duplicados exigem reconciliação.');
ctx.effects.push('Arquivo preservado no Drive: '+f.getUrl());
if(previous)change_(ctx,'Documentos',previous.id,Object.assign({},previous,{vigente:false}),previous.versao);
const d=change_(ctx,'Documentos',did,{atendimentoId:a.id,categoria:q.categoria,fileId:f.getId(),url:f.getUrl(),nome:name,hash:digest,mime:q.mime,substituiId:q.substituiId||'',vigente:true,vencimento:q.vencimento||'',terceiro:bool_(q.terceiro),conferido:false});
const changed=touch_(ctx,Object.assign({},a,{folderId:folder.getId()}));
return {documento:d,atendimento:changed,mensagem:'Arquivo gravado. Conferência humana pendente.'};
}

const MODULES={PAINEL:'Painel',PESS:'Pessoas',ATEND:'Atendimentos',ACOMP:'Ficha e conferência',MIN:'Minutas',ADM:'Administração',DIST:'Distribuição',PROC:'Processos'};
function doGet(){authorize_('consulta');
return HtmlService.createTemplateFromFile('Index').evaluate().setTitle(PDA.name).addMetaTag('viewport','width=device-width, initial-scale=1');
}
function include_(name){return HtmlService.createHtmlOutputFromFile(name).getContent();
}
function carregarModulo(code){authorize_(code==='ADM'?'administracao':'consulta');
if(!MODULES[code])fail_('Módulo inválido.');
return {view:include_(code+'_View'),style:include_(code+'_Style'),script:include_(code+'_Script')};
}
function api(action,q){resetData_();
q=q||{};
Object.keys(q).forEach(k=>{if(k!=='base64'&&typeof q[k]==='string'&&q[k].length>6000)fail_('Campo muito longo: '+k);
});
const reads={bootstrap:()=>({email:identity_(),perfil:all_('Usuarios').find(u=>u.email===identity_()).perfil,config:cfg_(),modulos:MODULES}),pessoas:()=>personSearch_(q),pessoa:()=>get_('Pessoas',q.id),atendimentos:()=>all_('Atendimentos'),ficha:()=>dossier_(q),painel:()=>dashboard_(),admin:()=>({configuracoes:all_('Configuracoes'),usuarios:all_('Usuarios'),perfis:Object.keys(ROLES)}),aptidao:()=>eligibility_(get_('Atendimentos',q.id),true)};
 const mutations={pessoaSalvar:['cadastro',personSave_],atendimentoSalvar:['cadastro',atendSave_],upload:['cadastro',upload_],encaminhar:['cadastro',forward_],documentoConferir:['conferencia',checkDoc_],pendenciaSalvar:['retificacao',pendSave_],atendimentoConferir:['conferencia',checkAtend_],minutaGerar:['minuta',generate_],minutaRevisar:['minuta',reviewMin_],configSalvar:['administracao',adminSave_],usuarioSalvar:['administracao',userSave_]};
 if(reads[action]){authorize_(action==='admin'?'administracao':'consulta');
return reads[action]();
}if(!mutations[action])fail_('Operação desconhecida.');
return lock_(()=>{resetData_();
const email=authorize_(mutations[action][0]);
if(!/^[a-zA-Z0-9_-]{16,100}$/.test(q.op||''))fail_('Identificador de operação inválido.');
const op=id_('OP',email+':'+q.op);
const payload=clone_(q);
delete payload.op;
if(payload.base64){payload.contentHash=hash_(payload.base64);
delete payload.base64;
}const digest=hash_({action,payload});
const previous=all_('Operacoes').find(r=>r.id===op);
if(previous){if(previous.hash!==digest)fail_('Operação já utilizada com conteúdo diferente.');
return JSON.parse(previous.resultado);
}const ctx={email,op,hash:digest,changes:[],effects:[]};
try{const result=mutations[action][1](ctx,q);
return commit_(ctx,result);
}catch(e){if(ctx.effects.length)fail_(e.message+"\nEfeitos no Drive: "+ctx.effects.join("; ")+"\nRegistro transacional não confirmado. Repita a mesma operação para reconciliar.");
throw e;
}});
}

function dossier_(q){const p=get_('Pessoas',q.pessoaId);
const ats=all_('Atendimentos').filter(a=>a.pessoaId===p.id);
const ids=ats.map(a=>a.id);
const docs=all_('Documentos').filter(d=>ids.includes(d.atendimentoId));
const mins=all_('Minutas').filter(d=>ids.includes(d.atendimentoId)).map(m=>{const a=ats.find(a=>a.id===m.atendimentoId);
return Object.assign({},m,{desatualizada:m.snapshot!==snapshot_(a,p)||cfg_().templateId!==m.templateId||String(DriveApp.getFileById(m.templateId).getLastUpdated().getTime())!==m.templateModified});
});
const related=[p.id].concat(ids,docs.map(d=>d.id),mins.map(m=>m.id));
const pend=all_('Pendencias').filter(d=>ids.includes(d.atendimentoId));
pend.forEach(x=>related.push(x.id));
return {pessoa:p,atendimentos:ats,documentos:docs,pendencias:pend,minutas:mins,historico:all_('Historico').filter(h=>related.includes(h.registroId)),processos:all_('Processos').filter(x=>x.pessoaId===p.id),aptidao:ats.map(a=>({id:a.id,pendencias:eligibility_(a,true)}))};
}
